pub fn recordConstructorDef(
    mut txt: Tpl::Text,
    a_ctor__name: &ArcStr,
    a_rec__name: &ArcStr,
    a_variables: &metamodelica::List<metamodelica::Ref<SimCodeFunction::Variable::Variable>>,
) -> Result<Tpl::Text> {
    let mut l_varDecls;
    let mut l_varFrees;
    let mut l_auxFunction;
    let mut l_ctor__additional__inputs;
    let mut l_varInits;
    let mut out_txt;
    l_varDecls = (*Tpl::emptyTxt).clone();
    l_varFrees = (*Tpl::emptyTxt).clone();
    l_auxFunction = (*Tpl::emptyTxt).clone();
    (l_ctor__additional__inputs, l_auxFunction) = lm_154((*Tpl::emptyTxt).clone(), a_variables, l_auxFunction)?;
    (l_varInits, l_auxFunction, l_varFrees, l_varDecls) = lm_155(
        (*Tpl::emptyTxt).clone(),
        a_variables,
        l_auxFunction,
        l_varFrees,
        l_varDecls,
    )?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("void "),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_ctor__name.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("_construct_p(threadData_t *threadData, void* v_ths "),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_ctor__additional__inputs)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!(") {\n"),
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeStr(out_txt, a_rec__name.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("* ths = ("),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_rec__name.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!("*)(v_ths);\n"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_varDecls)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeText(out_txt, l_varInits)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!("_return: OMC_LABEL_UNUSED ;\n"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_varFrees)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }),
    )?;
    Ok(out_txt)
}

