fn fun_549(
    mut in_txt: Tpl::Text,
    mut in_mArg: i32,
    in_a_stmt: &metamodelica::Ref<DAE::Statement>,
    in_a_context: &SimCodeFunction::Context,
    mut in_a_varDecls: Tpl::Text,
    mut in_a_varFrees: Tpl::Text,
    mut in_a_auxFunction: Tpl::Text,
) -> Result<(Tpl::Text, Tpl::Text, Tpl::Text, Tpl::Text)> {
    ::match_deref::match_deref! { match (in_mArg, in_a_stmt, in_a_context) {
        (i_oldIndex, a_stmt, a_context) => {
            let mut txt = in_txt;
            let mut a_varDecls = in_a_varDecls;
            let mut a_varFrees = in_a_varFrees;
            let mut a_auxFunction = in_a_auxFunction;
            let mut l_res;
            let mut ret_1;
            let mut ret_2;
            (l_res, a_auxFunction, a_varFrees, a_varDecls) = fun_548((*Tpl::emptyTxt).clone(), a_stmt, a_auxFunction, a_varFrees, a_varDecls, a_context)?;
            System::tmpTickSetIndex(i_oldIndex, 1);
            ret_1 = Algorithm::getStatementSource(a_stmt)?;
            ret_2 = ElementSource::getElementSourceFileInfo(ret_1);
            txt = modelicaLine(txt, &ret_2)?;
            txt = Tpl::writeText(txt, l_res)?;
            txt = Tpl::softNewLine(txt)?;
            txt = errorCheck(txt, a_context)?;
            txt = endModelicaLine(txt)?;
            Ok((txt, a_varDecls, a_varFrees, a_auxFunction))
        }
        _ => Err("fun_549: no case matched"),
    } }
}

