pub fn functionsParModelicaKernelsFile(
    mut txt: Tpl::Text,
    a_filePrefix: &ArcStr,
    a_mainFunction: &Option<metamodelica::Ref<SimCodeFunction::Function::Function>>,
    a_functions: &metamodelica::List<metamodelica::Ref<SimCodeFunction::Function::Function>>,
) -> Result<Tpl::Text> {
    let mut out_txt;
    System::tmpTickResetIndex(0, 20);
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("#include <ParModelica/explicit/openclrt/OCLRuntimeUtil.cl>\n"),
                literal!("\n"),
                literal!("// ParModelica Parallel Function headers.\n")
            ],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = functionHeadersParModelica(out_txt, a_filePrefix, a_functions)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("\n"), literal!("// Headers finish here.\n"), literal!("\n")],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = fun_655(out_txt, a_mainFunction)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = functionBodiesParModelica(out_txt, a_functions)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("\n"), literal!("\n")],
            lastHasNewLine: true,
        }),
    )?;
    Ok(out_txt)
}

